// src/assets/products.js
const imageModules = import.meta.glob('./*.{png,jpg,jpeg,webp,svg}', { eager: true, import: 'default' });

const getImage = (fileName) => {
    if (!fileName) return "/products/microsoft_software.svg";
    if (fileName.startsWith('/')) return fileName;
    const rel = './' + fileName;
    return imageModules[rel] || fileName;
};

